import React from 'react';
import { Tooltip, type TooltipProps } from '../Tooltip';
import styles from './RadioGroup.module.css';

export interface RadioGroupOption {
  value: string;
  label: string;
  /** Hover hint — rendered via Tooltip (portal when inlineTooltip). */
  tooltip?: string;
}

export interface RadioGroupProps {
  name: string;
  value?: string;
  onChange: (value: string) => void;
  options: RadioGroupOption[];
  label?: string;
  error?: string;
  helperText?: string;
  required?: boolean;
  disabled?: boolean;
  layout?: 'horizontal' | 'vertical';
  tooltipPosition?: TooltipProps['position'];
  /**
   * Portal tooltips to document.body — avoids clipping in overflow:hidden parents.
   * Defaults to true when any option has tooltip.
   */
  inlineTooltip?: boolean;
  fullWidth?: boolean;
  compact?: boolean;
  className?: string;
  id?: string;
}

export const RadioGroup: React.FC<RadioGroupProps> = ({
  name,
  value = '',
  onChange,
  options,
  label,
  error,
  helperText,
  required,
  disabled,
  layout = 'horizontal',
  tooltipPosition = 'top',
  inlineTooltip,
  fullWidth = false,
  compact = false,
  className = '',
  id,
}) => {
  const groupId = id || `radio-group-${name}`;
  const hasTooltip = options.some((opt) => Boolean(opt.tooltip));
  const useInlineTooltip = inlineTooltip ?? hasTooltip;

  const renderOption = (opt: RadioGroupOption) => {
    const optionLabel = (
      <label className={styles.option}>
        <input
          type="radio"
          name={name}
          value={opt.value}
          checked={value === opt.value}
          onChange={() => onChange(opt.value)}
          disabled={disabled}
        />
        <span className={styles.optionText}>{opt.label}</span>
      </label>
    );

    if (!opt.tooltip) return <React.Fragment key={opt.value}>{optionLabel}</React.Fragment>;

    return (
      <Tooltip
        key={opt.value}
        content={opt.tooltip}
        position={tooltipPosition}
        inline={useInlineTooltip}
      >
        {optionLabel}
      </Tooltip>
    );
  };

  return (
    <div
      className={`${styles.container} ${fullWidth ? styles.fullWidth : ''} ${className}`}
      role="radiogroup"
      aria-labelledby={label ? `${groupId}-label` : undefined}
    >
      {label && (
        <span id={`${groupId}-label`} className={styles.label}>
          {label}
          {required && <span className={styles.required}>*</span>}
        </span>
      )}
      <div className={`${styles.options} ${styles[layout]} ${compact ? styles.compact : ''}`}>
        {options.map(renderOption)}
      </div>
      {error && <span className={styles.error}>{error}</span>}
      {!error && helperText && <span className={styles.helperText}>{helperText}</span>}
    </div>
  );
};
