/**
 * MonthYearPill — pill button with floating dropdown picker
 *
 * For month type: clicking the pill directly opens the browser's native month
 * picker via showPicker() on a hidden input — no intermediate dropdown step.
 * For year type: clicking toggles a scrollable <select> dropdown.
 */
import React, { useEffect, useRef, useState } from 'react';
import styles from './MonthYearPill.module.css';

interface MonthYearPillProps {
  type:    'month' | 'year';
  active:  boolean;
  /** YYYY-MM for month, "YYYY" string for year */
  value:   string;
  onChange:   (value: string) => void;
  onActivate: () => void;
  /** Max value (YYYY-MM for month) */
  max?:    string;
  minYear?: number;
  maxYear?: number;
}

const CURRENT_YEAR = new Date().getFullYear();

function formatLabel(type: 'month' | 'year', value: string): string {
  if (type === 'month') {
    const [y, m] = value.split('-').map(Number);
    if (!y || !m) return 'Tháng';
    return `Tháng ${m}/${y}`;
  }
  return `Năm ${value || CURRENT_YEAR}`;
}

function buildYearOptions(min: number, max: number): number[] {
  const years: number[] = [];
  for (let y = max; y >= min; y--) years.push(y);
  return years;
}

export const MonthYearPill: React.FC<MonthYearPillProps> = ({
  type,
  active,
  value,
  onChange,
  onActivate,
  max,
  minYear = 2000,
  maxYear = CURRENT_YEAR + 1,
}) => {
  const [open, setOpen] = useState(false);
  const wrapRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  // Year dropdown: open when pill becomes active
  useEffect(() => {
    if (type === 'year') {
      if (active) setOpen(true);
      else        setOpen(false);
    }
  }, [active, type]);

  // Close year dropdown on outside click
  useEffect(() => {
    if (!open || type === 'month') return;
    const onDown = (e: MouseEvent) => {
      if (wrapRef.current && !wrapRef.current.contains(e.target as Node)) {
        setOpen(false);
      }
    };
    document.addEventListener('mousedown', onDown);
    return () => document.removeEventListener('mousedown', onDown);
  }, [open, type]);

  const openMonthPicker = () => {
    try {
      inputRef.current?.showPicker?.();
    } catch {
      // showPicker() not supported — fallback: programmatically click the input
      inputRef.current?.click();
    }
  };

  const handlePillClick = () => {
    if (!active) onActivate();
    if (type === 'month') {
      openMonthPicker();
    } else {
      setOpen((v) => !v);
    }
  };

  const label = formatLabel(type, value);

  return (
    <div ref={wrapRef} className={styles.pillWrapper}>
      {/* Pill button — always same shape */}
      <button
        type="button"
        className={`${styles.pill} ${active ? styles.pillActive : ''}`}
        onClick={handlePillClick}
        title={type === 'month' ? 'Lọc theo tháng' : 'Lọc theo năm'}
      >
        {label}
        <i className={`fas fa-chevron-${open && type === 'year' ? 'up' : 'down'} ${styles.pillChevron}`} />
      </button>

      {/* Hidden month input — native picker opens directly from pill click */}
      {type === 'month' && (
        <input
          ref={inputRef}
          type="month"
          className={styles.hiddenMonthInput}
          value={value}
          max={max}
          onChange={(e) => { if (e.target.value) onChange(e.target.value); }}
          aria-hidden="true"
          tabIndex={-1}
        />
      )}

      {/* Year picker dropdown */}
      {type === 'year' && open && (
        <div className={styles.dropdown}>
          <select
            className={styles.dropdownSelect}
            value={value}
            onChange={(e) => {
              onChange(e.target.value);
              setOpen(false);
            }}
            size={Math.min(8, maxYear - minYear + 1)}
            aria-label="Chọn năm"
          >
            {buildYearOptions(minYear, maxYear).map((y) => (
              <option key={y} value={String(y)}>{y}</option>
            ))}
          </select>
        </div>
      )}
    </div>
  );
};

