import React, { useCallback, useEffect, useLayoutEffect, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import styles from './Tooltip.module.css';

export interface TooltipProps {
  content: string;
  children: React.ReactNode;
  position?: 'top' | 'right' | 'bottom' | 'left';
  disabled?: boolean;
  /** Inline wrapper — renders tooltip via portal to avoid overflow clipping. */
  inline?: boolean;
}

type TooltipPosition = NonNullable<TooltipProps['position']>;

const GAP_PX = 8;
const ARROW_PX = 5;
const VIEWPORT_MARGIN = 8;
const ESTIMATED_TIP = { width: 120, height: 28 };

function resolvePosition(
  anchor: DOMRect,
  tipWidth: number,
  tipHeight: number,
  preferred: TooltipPosition,
): TooltipPosition {
  const vw = window.innerWidth;
  const vh = window.innerHeight;
  const needV = tipHeight + GAP_PX + ARROW_PX;
  const needH = tipWidth + GAP_PX + ARROW_PX;

  const space = {
    top: anchor.top - VIEWPORT_MARGIN,
    bottom: vh - anchor.bottom - VIEWPORT_MARGIN,
    left: anchor.left - VIEWPORT_MARGIN,
    right: vw - anchor.right - VIEWPORT_MARGIN,
  };

  const pickVertical = (pref: 'top' | 'bottom'): 'top' | 'bottom' => {
    if (pref === 'top') {
      if (space.top >= needV) return 'top';
      if (space.bottom >= needV) return 'bottom';
      return space.bottom > space.top ? 'bottom' : 'top';
    }
    if (space.bottom >= needV) return 'bottom';
    if (space.top >= needV) return 'top';
    return space.bottom > space.top ? 'bottom' : 'top';
  };

  const pickHorizontal = (pref: 'left' | 'right'): 'left' | 'right' => {
    if (pref === 'left') {
      if (space.left >= needH) return 'left';
      if (space.right >= needH) return 'right';
      return space.right > space.left ? 'right' : 'left';
    }
    if (space.right >= needH) return 'right';
    if (space.left >= needH) return 'left';
    return space.right > space.left ? 'right' : 'left';
  };

  if (preferred === 'top' || preferred === 'bottom') return pickVertical(preferred);
  return pickHorizontal(preferred);
}

function clampAxisCenter(center: number, tipSize: number, viewportSize: number): number {
  const half = tipSize / 2;
  const min = VIEWPORT_MARGIN + half;
  const max = viewportSize - VIEWPORT_MARGIN - half;
  if (min > max) return viewportSize / 2;
  return Math.min(max, Math.max(min, center));
}

function getPortalStyle(
  rect: DOMRect,
  position: TooltipPosition,
  tipWidth: number,
  tipHeight: number,
): React.CSSProperties {
  const base: React.CSSProperties = { position: 'fixed', zIndex: 1070 };
  const vw = window.innerWidth;
  const vh = window.innerHeight;

  switch (position) {
    case 'top':
      return {
        ...base,
        top: rect.top - GAP_PX - ARROW_PX,
        left: clampAxisCenter(rect.left + rect.width / 2, tipWidth, vw),
        transform: 'translate(-50%, -100%)',
      };
    case 'bottom':
      return {
        ...base,
        top: rect.bottom + GAP_PX + ARROW_PX,
        left: clampAxisCenter(rect.left + rect.width / 2, tipWidth, vw),
        transform: 'translateX(-50%)',
      };
    case 'left':
      return {
        ...base,
        top: clampAxisCenter(rect.top + rect.height / 2, tipHeight, vh),
        left: rect.left - GAP_PX - ARROW_PX,
        transform: 'translate(-100%, -50%)',
      };
    case 'right':
      return {
        ...base,
        top: clampAxisCenter(rect.top + rect.height / 2, tipHeight, vh),
        left: rect.right + GAP_PX + ARROW_PX,
        transform: 'translateY(-50%)',
      };
    default:
      return base;
  }
}

export const Tooltip: React.FC<TooltipProps> = ({
  content,
  children,
  position = 'top',
  disabled = false,
  inline = false,
}) => {
  const wrapperRef = useRef<HTMLDivElement>(null);
  const tooltipRef = useRef<HTMLDivElement>(null);
  const [isVisible, setIsVisible] = useState(false);
  const [resolvedPosition, setResolvedPosition] = useState<TooltipPosition>(position);
  const [portalStyle, setPortalStyle] = useState<React.CSSProperties>({});

  const updatePosition = useCallback(() => {
    const anchor = wrapperRef.current?.getBoundingClientRect();
    if (!anchor) return;

    const tipRect = tooltipRef.current?.getBoundingClientRect();
    const tipWidth = tipRect?.width || ESTIMATED_TIP.width;
    const tipHeight = tipRect?.height || ESTIMATED_TIP.height;
    const nextPosition = resolvePosition(anchor, tipWidth, tipHeight, position);

    setResolvedPosition(nextPosition);
    setPortalStyle(getPortalStyle(anchor, nextPosition, tipWidth, tipHeight));
  }, [position]);

  const show = useCallback(() => {
    setResolvedPosition(position);
    setIsVisible(true);
  }, [position]);

  const hide = useCallback(() => {
    setIsVisible(false);
    setResolvedPosition(position);
  }, [position]);

  useLayoutEffect(() => {
    if (!isVisible || !inline) return;
    updatePosition();
  }, [isVisible, inline, content, updatePosition]);

  useEffect(() => {
    if (!isVisible || !inline) return;

    const onScrollOrResize = () => updatePosition();
    window.addEventListener('scroll', onScrollOrResize, true);
    window.addEventListener('resize', onScrollOrResize);
    return () => {
      window.removeEventListener('scroll', onScrollOrResize, true);
      window.removeEventListener('resize', onScrollOrResize);
    };
  }, [isVisible, inline, updatePosition]);

  if (disabled) return <>{children}</>;

  const activePosition = inline ? resolvedPosition : position;

  const tooltipNode = (
    <div
      ref={inline ? tooltipRef : undefined}
      className={`${styles.tooltip} ${styles[activePosition]} ${inline ? styles.portal : ''}`}
      style={inline ? portalStyle : undefined}
    >
      {content}
    </div>
  );

  return (
    <div
      ref={wrapperRef}
      className={`${styles.tooltipWrapper} ${inline ? styles.inline : ''}`}
      onMouseEnter={show}
      onMouseLeave={hide}
    >
      {children}
      {isVisible && !inline && tooltipNode}
      {isVisible && inline && createPortal(tooltipNode, document.body)}
    </div>
  );
};
